style.css:
@-moz-document url-prefix("https://discord.com/app") {
/* Import Minecraftia font (pixel-style) */
  @font-face {
    font-family: 'Minecraftia';
    src: url('https://dl.dafont.com/dl/?f=minecraftia') format('truetype');
  }

  :root, .theme-dark, .theme-light {
    --accent-1: #00aa00;   /* Minecraft green */
    --accent-2: #55ffff;   /* Aqua */
    --brand-experiment: var(--accent-1);
    --brand-500: var(--accent-1);
    --text-link: var(--accent-2);
    --font-primary: 'Minecraftia', 'Press Start 2P', monospace;
    --font-display: var(--font-primary);
    --radius-xs: 8px;
    --radius-sm: 12px;
    --radius-md: 16px;
    --radius-lg: 20px;
    --background-primary: rgba(0, 0, 0, 0.65);
    --background-secondary: rgba(0, 0, 0, 0.55);
    --background-tertiary: rgba(0, 0, 0, 0.75);
    --channeltextarea-background: rgba(0,0,0,0.6);
  }

  * {
    font-family: var(--font-primary) !important;
    letter-spacing: 0.5px;
  }

  /* Bubble chat */
  [class*="message-"], [class*="messageContent-"] {
    background: rgba(0,0,0,0.4) !important;
    border-radius: var(--radius-lg) !important;
    padding: 6px 10px !important;
    margin: 4px 0 !important;
    border: 1px solid rgba(255,255,255,0.08) !important;
    display: inline-block;
    max-width: 80%;
  }

  /* Compact message spacing */
  [class*="message-"], [class*="cozyMessage-"], [class*="compactMessage-"] {
    padding-top: 2px !important;
    padding-bottom: 2px !important;
  }

  /* Smaller server list */
  nav[aria-label="Servers"] {
    width: 56px !important;
  }

  /* Rounded popouts */
  [role="dialog"], [role="menu"], [class*="popout"], [class*="tooltip"] {
    border-radius: var(--radius-lg) !important;
  }

  /* Accent buttons */
  .mention, [class*="lookFilled-"], [class*="colorBrand-"] {
    background: var(--accent-1) !important;
    color: white !important;
    border-radius: var(--radius-md) !important;
  }
}
